<?php elseif($step==='result'&&$resultRow):?><section class="card"><span class="kicker">EXAM COMPLETE</span><div class="result"><?=(int)round((float)($resultBreakdown['summary']['percent']??$resultRow['pct']??0))?>%</div><h1 class="title" style="text-align:center"><?=ev_h($resolvedTitle)?></h1><div class="chips" style="justify-content:center"><span class="chip">Score <?=ev_h(number_format((float)($resultBreakdown['summary']['earned']??$resultRow['score']??0),2,'.',''))?> / <?=ev_h(number_format((float)($resultBreakdown['summary']['possible']??$resultRow['max_score']??0),2,'.',''))?></span><span class="chip">Attempt <?=$attemptsUsed?> / <?=$resolvedMaxAttempts?></span></div><?php if(!empty($resultBreakdown['totals'])):?><div style="overflow-x:auto;margin-top:18px"><table style="width:100%;border-collapse:collapse;font-size:14px"><thead><tr><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Actividad</th><th style="text-align:right;padding:10px;border-bottom:1px solid var(--line)">Puntos obtenidos</th><th style="text-align:right;padding:10px;border-bottom:1px solid var(--line)">Puntos posibles</th><th style="text-align:right;padding:10px;border-bottom:1px solid var(--line)">Porcentaje</th></tr></thead><tbody><?php foreach($resultBreakdown['totals'] as $row):?><tr><td style="padding:10px;border-bottom:1px solid var(--line)"><?=ev_h($row['activity']??'Activity')?></td><td style="padding:10px;border-bottom:1px solid var(--line);text-align:right"><?=ev_h(number_format((float)($row['earned']??0),2,'.',''))?></td><td style="padding:10px;border-bottom:1px solid var(--line);text-align:right"><?=ev_h(number_format((float)($row['possible']??0),2,'.',''))?></td><td style="padding:10px;border-bottom:1px solid var(--line);text-align:right"><?=ev_h(number_format((float)($row['percent']??0),2,'.',''))?>%</td></tr><?php endforeach;?><tr><td style="padding:10px;font-weight:900">Total</td><td style="padding:10px;text-align:right;font-weight:900"><?=ev_h(number_format((float)($resultBreakdown['summary']['earned']??0),2,'.',''))?></td><td style="padding:10px;text-align:right;font-weight:900"><?=ev_h(number_format((float)($resultBreakdown['summary']['possible']??0),2,'.',''))?></td><td style="padding:10px;text-align:right;font-weight:900"><?=ev_h(number_format((float)($resultBreakdown['summary']['percent']??0),2,'.',''))?>%</td></tr></tbody></table></div><?php endif;?><div class="actions"><?php if($canRetake):?><a class="btn orange" href="eval_viewer.php?<?=ev_h(http_build_query(['t'=>$token,'step'=>'welcome']))?>">Take again</a><?php endif;?><button class="btn light" type="button" onclick="window.close();history.length>1&&history.back();">Close</button></div></section><?php else:?><section class="card"><h1 class="title">Exam unavailable</h1></section><?php endif;?></div></body></html>
<?php
// Unit exams use the exact same activity views as the unit quiz. The exam
// controller still owns identity, attempts, persistence, timing, and results.
if($isUnitExam&&$step==='quiz'&&$currentQuestion){
    $GLOBALS['mode']='quiz';
    $GLOBALS['qzEvalInjectorContext']=true;
    require __DIR__.'/../quiz/_quiz_injector.php';
?>
<script>
(function(){
    var qIndex=<?=json_encode($qIndex)?>;
    document.querySelectorAll('[id^="qz"][id$="_holder"] form').forEach(function(form){
        if(!form.querySelector('input[name="eval_answer"]')){
            var marker=document.createElement('input');
            marker.type='hidden';marker.name='eval_answer';marker.value='1';
            form.appendChild(marker);
        }
        if(!form.querySelector('input[name="q_index"]')){
            var indexInput=document.createElement('input');
            indexInput.type='hidden';indexInput.name='q_index';indexInput.value=String(qIndex);
            form.appendChild(indexInput);
        }
    });
})();
</script>
<?php } ?>
